-- Student Resources: first entries, researched 2026-11-23 from official or primary sources.
--
-- Every entry starts as PENDING, so a Perqly admin reviews and approves it before students see it.
-- "featured" is the researcher's suggestion; it only shows once the entry is published.
-- Entries marked needs_verification say so to students. Entries with no checked_on were not
-- checked in this round and must be checked before approval.

insert into public.student_resources (
  slug, name, provider, category, offer_type, offer_label, summary, description, benefits, requirements_note,
  eligibility, availability, needs_school_email, needs_student_proof, needs_institution_listed, needs_payment_card,
  min_age, official_url, source_url, checked_on, featured, status)
select v.*, 'pending'::public.resource_status from (values
  ('github-student-developer-pack', 'GitHub Student Developer Pack', 'GitHub', 'developer_tools'::public.resource_category, 'free_for_students'::public.resource_offer_type, 'Free while studying', 'Free developer tools and services from GitHub and its partners for verified students.', 'GitHub Education gives verified students a free Developer plan on GitHub and a collection of 80+ partner tools and offers in one pack. It''s open to students in a degree or diploma course anywhere, and you can reapply when your access expires while you''re still a student.', array['Free GitHub Developer plan with unlimited private repositories', '80+ partner tools and offers in one place', 'Also unlocks some other student programmes, such as JetBrains']::text[], 'Aged 13 or older and enrolled in a degree or diploma course. Verify with a school email address and/or dated, official proof of enrolment.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, true, false, false, 13, 'https://education.github.com/pack', 'https://github.com/education/students', '2026-11-23'::date, true),
  ('aws-educate', 'AWS Educate', 'Amazon Web Services', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free, no card', 'Free self-paced cloud computing and AI training with hands-on labs and digital badges.', 'AWS Educate is Amazon''s free, self-paced cloud learning programme for beginners. You sign up with an email address, then take courses and practise in hands-on labs without paying or adding a card.', array['Free self-paced cloud and AI courses', 'Hands-on labs in the AWS console', 'Digital badges you can share', 'Helps you prepare for the AWS Certified Cloud Practitioner exam (exam fee not included)']::text[], 'An email address. Minimum age depends on your country under the AWS Learner Terms (13 in most countries). No credit card needed.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, 13, 'https://aws.amazon.com/education/awseducate/', 'https://aws.amazon.com/educate', '2026-11-23'::date, true),
  ('ibm-skillsbuild', 'IBM SkillsBuild', 'IBM', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free credentials', '1,000+ free online courses in AI, cybersecurity, data and workplace skills, with IBM digital credentials.', 'IBM SkillsBuild is a free education programme for students and adult learners. Courses cover technology and professional skills, and completing them earns IBM-branded digital credentials you can share on LinkedIn or your CV.', array['1,000+ free online courses', 'IBM digital credentials through Credly', 'Topics include AI, cybersecurity, data analytics and workplace skills']::text[], 'Free account. You must be at least 13.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, 13, 'https://skillsbuild.org', 'https://skillsbuild.org/about', '2026-11-23'::date, false),
  ('cisco-networking-academy', 'Cisco Networking Academy', 'Cisco', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free self-paced', 'Free self-paced courses in networking, cybersecurity and programming, plus Cisco Packet Tracer.', 'Cisco Networking Academy offers free self-paced online courses that you can join on your own, and instructor-led courses through partner academies. Registered learners can download Cisco Packet Tracer, the network simulation tool.', array['Free self-paced networking, cybersecurity and programming courses', 'Certificates of completion and badges', 'Cisco Packet Tracer for registered learners', 'Courses aligned to industry certifications']::text[], 'Free account. Some instructor-led courses are only through a partner academy or school.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, null, 'https://www.netacad.com', 'https://www.cisco.com/site/us/en/learn/training-certifications/training/netacad/index.html', '2026-11-23'::date, true),
  ('microsoft-learn', 'Microsoft Learn', 'Microsoft', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free training', 'Free self-paced training paths for Microsoft technologies, with a Student Hub for certification prep.', 'Microsoft Learn has free modules and learning paths on Azure, AI, data, Power Platform and more. The Student Hub helps students pick a credential and prepare for the exam.', array['Free self-paced modules and learning paths', 'Student Hub for choosing and preparing for credentials', 'Practice content to get exam-ready']::text[], 'Free Microsoft account.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, null, 'https://learn.microsoft.com/training/student-hub/', 'https://learn.microsoft.com/en-us/training/student-hub/certifications', '2026-11-23'::date, false),
  ('microsoft-certification-student-pricing', 'Microsoft Certification student exam pricing', 'Microsoft', 'discounts_trials'::public.resource_category, 'paid_exam'::public.resource_offer_type, 'Student exam price', 'Academic pricing on Microsoft Certification exams for verified students.', 'Microsoft offers academic pricing on its certification exams in most countries and regions, with India and China excluded. You mark yourself as a student in your Learn profile, verify your academic status, and the discount applies when you register for an exam. The exam is still paid.', array['Lower price on Microsoft Certification exams', 'Applied when you register for the exam']::text[], 'Verify your academic status in your Microsoft Learn profile. The exact price in Ghana hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'international'::public.resource_availability, false, true, false, true, null, 'https://learn.microsoft.com/certifications/student-discounts', 'https://learn.microsoft.com/en-us/certifications/student-discounts', '2026-11-23'::date, false),
  ('azure-for-students', 'Azure for Students', 'Microsoft', 'developer_tools'::public.resource_category, 'free_for_students'::public.resource_offer_type, '$100 Azure credit', '$100 of Azure cloud credit for 12 months plus free services, with no credit card at sign-up.', 'Azure for Students gives students at higher-education institutions $100 in Azure credit to use within 12 months, plus free access to some services. It renews each year you''re a student. Activations are limited and the offer runs while supplies last.', array['$100 Azure credit for 12 months', 'Free tiers of selected Azure services', 'Renewable each year you''re a student', 'No credit card at sign-up']::text[], 'You must verify your academic status with your institution''s email address. Whether GCTU emails are accepted hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, true, false, true, false, null, 'https://azure.microsoft.com/free/students/', 'https://learn.microsoft.com/en-us/azure/education-hub/about-azure-for-students', '2026-11-23'::date, false),
  ('figma-education', 'Figma for Education', 'Figma', 'design_creativity'::public.resource_category, 'free_for_students'::public.resource_offer_type, 'Free Professional plan', 'Figma''s Professional plan free for verified higher-education students.', 'Figma for Education gives students the Professional plan free. Higher-education students apply with their school-issued email and complete SheerID verification. Access lasts one year for students, then you re-verify.', array['Figma Professional plan free', 'Collaborate on an Education team', 'Renew each year while you''re a student']::text[], 'School-issued email and SheerID verification. Whether GCTU is recognised hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, true, true, true, false, null, 'https://www.figma.com/education/apply', 'https://help.figma.com/hc/en-us/articles/360041061214-verify-your-education-status', '2026-11-23'::date, true),
  ('notion-education', 'Notion Education Plus', 'Notion', 'ai_productivity'::public.resource_category, 'free_for_students'::public.resource_offer_type, 'Free Plus plan', 'Notion''s Plus plan free for students who sign in with a school email.', 'Individual students at accredited colleges and universities can upgrade to Notion''s Plus plan free. Your school email must be the main email on your Notion account, and the school''s domain must be recognised. Verify once a year to keep it. Student organisations can apply for a separate free team plan.', array['Plus plan free: unlimited pages and blocks, file uploads, 30-day page history', 'Up to 100 guests', 'Discounted Notion AI for eligible students']::text[], 'A school email as your main Notion email. Notion doesn''t accept student IDs. Whether GCTU''s domain is recognised hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, true, false, true, false, null, 'https://www.notion.com/product/notion-for-education', 'https://www.notion.com/en-us/help/notion-for-education', '2026-11-23'::date, false),
  ('spotify-premium-student', 'Spotify Premium Student', 'Spotify', 'entertainment_lifestyle'::public.resource_category, 'discounted'::public.resource_offer_type, 'Student price', 'Spotify Premium at a student price in Ghana for verified university students.', 'Spotify sells a Premium Student plan in Ghana at a lower monthly price than Premium Individual. Student status is checked by SheerID, and your university or college must be on its list. Check the current price on Spotify before you subscribe.', array['Ad-free music', 'Download to listen offline', 'Discounted monthly price for students']::text[], 'Enrolled at an accredited higher-education institution, verified by SheerID; your school must be on the list. A payment method is needed. GCTU''s listing hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'ghana'::public.resource_availability, false, true, true, true, null, 'https://www.spotify.com/gh-en/premium/', 'https://ghanamusic.com/news/from-the-industry/2024/04/09/spotify-raises-monthly-fees-for-premium-subscriptions-in-ghana', '2026-11-23'::date, true),
  ('google-career-certificates-ghana', 'Google Career Certificates scholarships (Ghana)', 'Google', 'career_internships'::public.resource_category, 'funded'::public.resource_offer_type, 'Scholarship', 'Scholarships for Google Career Certificates in Ghana, through the One Million Coders Programme.', 'Google announced 100,000 Google Career Certificate scholarships in Ghana, distributed through the One Million Coders Programme. The certificates are flexible online programmes in fields like data analytics, cybersecurity, UX design and project management. Outside the scholarship, Coursera also offers financial aid on the course pages.', array['Covers a Google Career Certificate on Coursera', 'Self-paced, job-focused online training', 'Financial aid on Coursera as an alternative']::text[], 'Apply through the One Million Coders Programme when a wave is open. Check the current wave''s requirements before applying.', 'confirmed'::public.resource_eligibility, 'ghana'::public.resource_availability, false, false, false, false, null, 'https://grow.google/certificates/', 'https://blog.google/intl/en-africa/company-news/outreach-and-initiatives/applications-now-open-100000-google-career-certificate-scholarships-in-ghana/', '2026-11-23'::date, true),
  ('coursera-financial-aid', 'Coursera financial aid', 'Coursera', 'learning_certifications'::public.resource_category, 'funded'::public.resource_offer_type, 'Financial aid', 'Apply for financial aid on eligible Coursera courses and certificates.', 'Many Coursera courses and professional certificates, including Google Career Certificates, have a "Financial aid available" link beside the Enrol button. Approved learners get full access to the course content and assignments needed for the certificate.', array['Full access to graded content when approved', 'Earn the certificate without paying the course fee']::text[], 'Apply on each course page and explain your circumstances. Not every course offers aid.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, null, 'https://www.coursera.org', 'https://grow.google/certificates/en_ca/', '2026-11-23'::date, false),
  ('alx-ghana', 'ALX Ghana tech programmes', 'ALX', 'career_internships'::public.resource_category, 'funded'::public.resource_offer_type, 'Sponsored places', 'Tech training in software engineering, data and cloud, with sponsored places for eligible learners.', 'ALX runs tech training programmes in Ghana, including software engineering, data analytics and cloud, with a hub in Accra. It has offered sponsored places for eligible learners. Programmes and intakes change, so check what''s open now.', array['Software engineering, data and cloud programmes', 'Learner community and hubs in Accra', 'Career support']::text[], 'Programmes, intakes and sponsorship terms change; check current eligibility on ALX''s site.', 'needs_verification'::public.resource_eligibility, 'ghana'::public.resource_availability, false, false, false, false, null, 'https://tech.alxafrica.com/ghana', 'https://tech.alxafrica.com/ghana', '2026-11-23'::date, false),
  ('jetbrains-student', 'JetBrains free educational licences', 'JetBrains', 'developer_tools'::public.resource_category, 'free_for_students'::public.resource_offer_type, 'Free IDEs', 'Free access to all JetBrains IDEs, such as IntelliJ IDEA and PyCharm, for students.', 'JetBrains gives students at accredited institutions free individual licences for its IDEs, for personal use at school or at home. Licences last a year and renew while you''re a student.', array['All JetBrains IDEs free', 'Renew yearly while you study', 'Graduation discount when you finish']::text[], 'Verify with a school email, an ISIC/ITIC card, or your GitHub Student Developer Pack. Your programme must take a year or more of full-time study.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, true, false, false, null, 'https://www.jetbrains.com/community/education/#students', 'https://jetbrains.com/student', '2026-11-23'::date, false),
  ('autodesk-education', 'Autodesk Education plan', 'Autodesk', 'design_creativity'::public.resource_category, 'free_for_students'::public.resource_offer_type, 'Free for a year', 'Free one-year access to Autodesk software like AutoCAD, Revit and Fusion for education.', 'Autodesk''s Education plan gives eligible students free one-year, single-user access to its software and services for learning. It renews each year you''re eligible. It''s for education only, not commercial work.', array['AutoCAD, Revit, Fusion and more', 'Install on up to three devices', 'Renewable yearly while eligible']::text[], 'Proof of enrolment verified by SheerID, and a minimum age. Whether GCTU is recognised hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, true, true, false, null, 'https://www.autodesk.com/education/edu-software/overview', 'https://www.autodesk.com/support/account/education/students-educators/overview', '2026-11-23'::date, false),
  ('google-summer-of-code', 'Google Summer of Code', 'Google', 'career_internships'::public.resource_category, 'funded'::public.resource_offer_type, 'Paid stipend', 'Remote, paid open-source coding projects for students and beginners, with mentors.', 'Google Summer of Code pairs students and open-source beginners with mentoring organisations for a remote coding project of about 12 weeks. Contributors who pass the evaluations earn a stipend, which varies by project size and country.', array['Paid stipend', 'Fully remote, with a mentor', 'Real open-source experience for your CV']::text[], '18 or older at registration, a student or open-source beginner, and eligible to work in your country during the programme. Applications open once a year.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, 18, 'https://summerofcode.withgoogle.com', 'https://summerofcode.withgoogle.com/get-started', '2026-11-23'::date, true),
  ('outreachy', 'Outreachy internships', 'Outreachy', 'career_internships'::public.resource_category, 'funded'::public.resource_offer_type, '$7,000 stipend', 'Paid, remote three-month internships in open source for people underrepresented in tech.', 'Outreachy offers remote internships in open source and open science twice a year, with a $7,000 USD stipend. Internships include coding and non-coding work. It''s open to applicants around the world who meet its eligibility rules.', array['$7,000 USD stipend', 'Fully remote, three months', 'Coding and non-coding projects']::text[], 'Eligibility rules change by round and depend on your circumstances; check the current rules before applying.', 'needs_verification'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, null, 'https://www.outreachy.org', 'https://www.outreachy.org/docs/applicant', '2026-11-23'::date, false),
  ('un-online-volunteering', 'UN Online Volunteering', 'United Nations Volunteers (UNV)', 'career_internships'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Volunteer', 'Remote volunteer assignments with UN entities and organisations, from anywhere.', 'UNV''s Online Volunteering lets you contribute your skills to UN entities, governments and organisations remotely. Assignments are task-based and flexible. They''re unpaid, but you get experience and a certificate of appreciation from the host organisation.', array['Remote and flexible', 'Real-world experience with UN and partner organisations', 'Certificate of appreciation']::text[], '18 or older, with a profile on UNV''s Unified Volunteering Platform. Unpaid.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, 18, 'https://app.unv.org', 'https://www.unv.org/become-online-volunteer', '2026-11-23'::date, false),
  ('students-loan-trust-fund', 'Students Loan Trust Fund', 'Students Loan Trust Fund (SLTF)', 'finance_student_services'::public.resource_category, 'loan'::public.resource_offer_type, 'Student loan', 'Government student loans for Ghanaian tertiary students to help with fees and study costs.', 'The Students Loan Trust Fund gives loans to Ghanaian students on accredited undergraduate programmes at accredited tertiary institutions, to help with fees and other study costs. Evening and weekend students can apply; sandwich students currently can''t. SLTF says it charges no fee to apply.', array['Helps cover fees and study costs', 'Apply online with your Ghana Card', 'Evening and weekend students eligible']::text[], 'Ghanaian, admitted to an accredited undergraduate programme (diploma or degree) at an accredited institution, with a Ghana Card. It''s a loan you repay.', 'confirmed'::public.resource_eligibility, 'ghana'::public.resource_availability, false, true, false, false, null, 'https://www.sltf.gov.gh', 'https://www.sltf.gov.gh/loans/', '2026-11-23'::date, true),
  ('mastercard-foundation-scholars', 'Mastercard Foundation Scholars Program', 'Mastercard Foundation', 'finance_student_services'::public.resource_category, 'funded'::public.resource_offer_type, 'Full scholarship', 'Full scholarships at partner universities for academically talented African students with financial need.', 'The Mastercard Foundation Scholars Program funds students through partner universities, including KNUST and Ashesi in Ghana. Support can include tuition, accommodation, a stipend and mentoring. Each partner university runs its own application and deadlines.', array['Full tuition and living support', 'Mentoring and leadership development', 'Alumni network']::text[], 'Apply through a partner university. Criteria include academic record and financial need; each university sets its own rules and dates.', 'needs_verification'::public.resource_eligibility, 'ghana'::public.resource_availability, false, false, false, false, null, 'https://mastercardfdn.org', 'https://www.timeshighereducation.com/student/news/scholarship-month-mastercard-foundation-scholarship-programme', '2026-11-23'::date, false),
  ('tony-elumelu-foundation', 'TEF Entrepreneurship Programme', 'Tony Elumelu Foundation', 'business_entrepreneurship'::public.resource_category, 'funded'::public.resource_offer_type, '$5,000 seed capital', '$5,000 non-refundable seed capital, business training and mentoring for African entrepreneurs.', 'The Tony Elumelu Foundation Entrepreneurship Programme is open to founders in all 54 African countries with a business idea or young business. Selected entrepreneurs get training, mentoring and US$5,000 in non-refundable seed capital. Applications open once a year on TEFConnect.', array['US$5,000 non-refundable seed capital', 'Business management training', 'Mentoring and Africa-wide network']::text[], 'African entrepreneur with a business idea or early-stage business. Applications open once a year; check TEFConnect for the current window.', 'confirmed'::public.resource_eligibility, 'ghana'::public.resource_availability, false, false, false, false, null, 'https://www.tefconnect.com', 'https://www.tonyelumelufoundation.org/?p=28248', '2026-11-23'::date, true),
  ('mest-africa', 'MEST Africa Training Program', 'MEST Africa (Meltwater Foundation)', 'business_entrepreneurship'::public.resource_category, 'funded'::public.resource_offer_type, 'Fully sponsored', 'A fully sponsored 12-month tech entrepreneurship programme in Accra.', 'MEST Africa runs a fully sponsored, 12-month programme in Accra covering software development, business and communication, for people who want to start a software company. MEST has also funded startups from its programme.', array['Fully sponsored 12-month training in Accra', 'Software development, business and communication', 'Possible startup funding']::text[], 'Aspiring founders from across Africa who can commit full-time for 12 months in Accra. Age limits and intake dates change; check the current call.', 'needs_verification'::public.resource_eligibility, 'ghana'::public.resource_availability, false, false, false, false, null, 'https://meltwater.org', 'https://meltwater.org/?p=8542', '2026-11-23'::date, false),
  ('hult-prize', 'Hult Prize', 'Hult Prize Foundation', 'business_entrepreneurship'::public.resource_category, 'free_for_students'::public.resource_offer_type, '$1M prize', 'A global student startup competition for social enterprises, with US$1M for the winning team.', 'The Hult Prize challenges university students to build for-profit startups that support at least one UN Sustainable Development Goal. Teams compete on campus or apply online, and one team wins US$1M in seed funding. Students can also run Hult Prize on their own campus.', array['US$1M seed funding for the winner', 'Mentoring and a global network', 'Run it on your campus as a Campus Director']::text[], 'A team of eligible university students. Enter through a campus programme or the online application.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, null, 'https://www.hultprize.org/become-a-competitor/', 'https://www.hultprize.org/how-it-works', '2026-11-23'::date, false),
  ('freecodecamp', 'freeCodeCamp', 'freeCodeCamp', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free certifications', 'Learn to code with thousands of lessons and earn free verified certifications.', 'freeCodeCamp is a nonprofit with a free, self-paced curriculum in web development, Python, computer science and more. Courses, projects and certifications are all free.', array['Free verified certifications', 'Hundreds of hands-on projects', 'Works in the browser']::text[], 'Free account.', 'confirmed'::public.resource_eligibility, 'international'::public.resource_availability, false, false, false, false, null, 'https://www.freecodecamp.org/learn', 'https://www.freecodecamp.org/about/', '2026-11-23'::date, false),
  ('google-ai-plus-students', 'Google AI Plus for students', 'Google', 'discounts_trials'::public.resource_category, 'free_trial'::public.resource_offer_type, '12 months free', 'A year of Google AI Plus (Gemini) free for eligible university students in selected African countries.', 'Google offers eligible college and university students in 27 African countries 12 months of Google AI Plus free, with higher Gemini limits and extra storage. Whether Ghana is included and how verification works there hasn''t been checked.', array['Higher Gemini usage limits', 'Extra Google storage', 'Study tools in Gemini']::text[], 'Eligible university students in participating countries; verification and sign-up rules vary. Ghana''s eligibility hasn''t been checked.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, true, true, false, 18, 'https://blog.google/intl/en-africa/one-year-of-gemini-on-us-for-students/', 'https://blog.google/intl/en-africa/one-year-of-gemini-on-us-for-students/', '2026-11-23'::date, false),
  ('cs50', 'CS50: Introduction to Computer Science', 'Harvard University', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free course', 'Harvard''s introduction to computer science, free online.', 'A well-known introductory computer science course from Harvard that you can take online.', array['Lectures, problem sets and projects']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://cs50.harvard.edu/x/', null, null, false),
  ('khan-academy', 'Khan Academy', 'Khan Academy', 'learning_certifications'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free', 'Free lessons and practice in maths, science, computing and more.', 'A nonprofit learning site with videos and practice exercises.', array['Maths, science and computing lessons', 'Practice exercises']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://www.khanacademy.org', null, null, false),
  ('kaggle-learn', 'Kaggle Learn', 'Kaggle', 'ai_productivity'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free courses', 'Short free courses in Python, machine learning and data science.', 'Kaggle Learn has short, hands-on courses you can complete in the browser.', array['Python, pandas and machine learning courses', 'Hands-on notebooks']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://www.kaggle.com/learn', null, null, false),
  ('canva-free', 'Canva Free', 'Canva', 'design_creativity'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free plan', 'Free design tool for posters, slides and social media graphics.', 'Canva''s free plan lets you design with templates in the browser or app.', array['Templates for posters, slides and social posts']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://www.canva.com', null, null, false),
  ('audiomack', 'Audiomack', 'Audiomack', 'entertainment_lifestyle'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free with ads', 'Free music streaming, popular with African artists.', 'Audiomack is a music streaming app with a free tier.', array['Free streaming with ads']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://audiomack.com', null, null, false),
  ('duolingo', 'Duolingo', 'Duolingo', 'entertainment_lifestyle'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free with ads', 'Learn a new language for free in short daily lessons.', 'Duolingo''s free tier offers short language lessons.', array['Short daily lessons', 'Many languages, including French']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://www.duolingo.com', null, null, false),
  ('chatgpt-free', 'ChatGPT (free plan)', 'OpenAI', 'ai_productivity'::public.resource_category, 'free_forever'::public.resource_offer_type, 'Free plan', 'A free AI assistant for writing, studying and brainstorming.', 'ChatGPT has a free plan you can use with an account.', array['Free AI assistant']::text[], 'Not checked yet for this directory. Check the provider''s site for current terms and availability in Ghana.', 'needs_verification'::public.resource_eligibility, 'needs_verification'::public.resource_availability, false, false, false, false, null, 'https://chatgpt.com', null, null, false)
) as v
on conflict (slug) do nothing;
